// Exporting a function
export function greet() {
  return 'Hello!';
}

// Importing the function
import { greet } from './greet.js';
console.log(greet());

// Default export
export default function greet() {
  return 'Hi!';
}

// Importing default
import greet from './greet.js';
console.log(greet());

// math.js
export function add(a, b) {
  return a + b;
}

// app.js
import { add } from './math.js';
console.log(add(2, 3)); // 5

